// partial score=0.2414 date=2026-09-28
//
// IDENTITY. ILT thunk 0x00048D29 carries this name and has 14 ILT callers
// (?findGroundPath@Pathfinder x10 plus four callback sites), so the body is
// Pathfinder::clearCellForDiameter. ABI is six stack args (ret 0x18) and is
// PROVEN from the body, so the mangled name is the I-form, NOT the six-H form:
//   [esp+0x2c] arg1 crusher, compared UNSIGNED (cmp eax,ecx / jbe) -> unsigned int (I)
//   [esp+0x30] arg2 cellX, [esp+0x34] arg3 cellY (cellY*16 cell stride: shl ebp,4)
//   [esp+0x38] arg4 layer, compared against 1 and 0xf -> PathfindLayerEnum (W4...@@)
//   [esp+0x3c] arg5 pathDiameter, [esp+0x40] arg6 read as a byte (mov al,[esp+0x40]) -> Bool (_N)
//   return eax (H) = 2*radius, or 1 when radius==0
// symbols.csv line 79935 still pins the ILT under the six-H name QAEHHHHHHH@Z; that
// is an over-claim (it resolves by address, so nothing is broken) and re_attempts.log
// line ~40359 carries a verdict under the same wrong name. Left alone: shared rows.
//
// SHAPE. ours=745 retail=729, 8 relocations, 521 non-reloc byte diffs, shape 0.960.
// Instruction-identical from +0x000 to +0x117 and again from the type check onward.
// The whole residue is ONE MSVC block-placement decision:
//
//   retail  [reload this +0x117][jbe +0x11b][FAIL BLOCK +0x11d .. +0x139]
//           [reload this +0x13e][type check +0x142 .. +0x165][latch +0x167]
//   ours    [ja +0x127 -> far FAIL][reload this +0x129][type check +0x12d .. +0x150]
//           [latch +0x152 .. +0x173][reload this +0x178][FAIL BLOCK +0x17c .. +0x199]
//
// i.e. the two block groups [reload | FAIL] and [reload | type check] are laid out in
// opposite order. The +16 is exactly four conditional jcc widenings, 2B short -> 6B near,
// all caused by the far block: R+0x9c jg, R+0xa1 jl, R+0xa6 jg, R+0xdd je.
// (R+0x93 jl is ALREADY near in retail, 0x84 > 0x7f, so it costs nothing either way;
// the type check's four backward jumps are short in both builds.) Those four fix the
// fail block's first byte T to [0x11A, 0x11D] -- T - 0x99 > 127 and T - 0x9e <= 127 --
// and retail uses 0x11D, so the fail block must be the fall-through of the crush-level
// compare. One discrete order choice, no size gradient to search.
//
// WHY NO SOURCE SPELLING REACHES IT. The two flow graphs are isomorphic entry for entry
// (fail block 10 entries in both, type-check group 3 in both, identical contents and
// sizes), and branch polarity is a CONSEQUENCE of the order, not a cause: MSVC re-decides
// it after ordering, so every polarity-inverting spelling is byte-identical. Proved
// disproved across 42 source graphs, 16 flag sets and the mechanical lever generator:
//   label position  - top of function (s6d), inline then-arm of !cell (k1), inline
//                      then-arm of the crush test (k2, literally retail's shape), loop
//                      bottom (n1/t810e), after the type check (y2), else-arm (y1/n2),
//                      and now the very END of the function (g1)
//   polarity        - h1/h2/h3, vF/vG, w1/w2, n5, k2: all byte-identical
//   failure spelling- one six-disjunct mega-OR (h4, byte-identical) vs the split chain;
//                      flattened (h5) is worse
//   retry mechanism - self tail recursion (base), goto Retry (t810e 731B, n8),
//                      a real for(;;) with goto Retry (p1 522B) or with continue (p2
//                      526B): a real loop makes MSVC unswitch on radius>1 and collapse
//                      the shape, so it is out
//   copies          - two textual copies DO tail-merge (x1/x2/k3), three do not (t810d)
//   inlining        - __forceinline on getCell (s6a) byte-identical; bounds test in a
//                      __forceinline helper with the null at the call site (s6b) 786B
//   loop spelling   - while+j++ in the inner loop (s6c) and in BOTH nests (h2):
//                      byte-identical
//   flags           - only /Ots (452B), /Oy- (711B) and /arch:SSE2 (750B) change the
//                      output at all; all far below 0.960, so no // cl: override
// g1 is the informative one: moving the fail label to the LAST statement in the function
// does change the bytes (725B), so flow-graph block numbering is a live input -- but it
// moves the block further from retail, not closer.
//
// EVIDENCE LOCATION. Per-session variants, both disassemblies and the run helpers are in
// build/scratch810/{s3,s4,s5,s6,s7}/; the full retail capstone decode is
// build/scratch810/retail810.txt (base 0x3DC810) and build/scratch810/s3_retail.bin is
// its raw 729 bytes for build/scratch810/align.py. Every verdict is in
// targets/game/reverse/re_attempts.log; the superseded per-session headers are in
// targets/game/reverse/attempt_history/0x003dc810.
//
// blocker=codegen-order/fail-block-placement-after-tail-merge. RECOMMEND THE PARENT
// RETIRE THIS BODY from graph-shape sessions: the residue needs a different compiler
// build, and inputs/toolchains holds only one (vs2003 Vc7, single c1xx.dll), so that
// lever does not exist on this host either.
typedef int Int;
typedef bool Bool;
typedef unsigned int UnsignedInt;
typedef unsigned char UnsignedByte;
typedef unsigned int ObjectID;

const ObjectID INVALID_ID = 0;

struct ICoord2D { Int x, y; };
struct IRegion2D { ICoord2D lo, hi; };

enum PathfindLayerEnum { LAYER_INVALID = 0, LAYER_GROUND = 1, LAYER_LAST = 15 };

class Object
{
public:
	UnsignedByte getCrushableLevel( void ) const;
};

class GameLogic
{
public:
	Object *findObjectByID( ObjectID id );
};

extern GameLogic *TheGameLogic;

class PathfindCellInfo
{
public:
	unsigned char m_prefix[0x14];
	ObjectID m_goalUnitID;
	ObjectID m_posUnitID;
	ObjectID m_bfme1C;
	ObjectID m_bfme20;
	UnsignedInt m_bfme24;
};

class PathfindCell
{
public:
	enum CellType { CELL_CLEAR = 0, CELL_OBSTACLE = 4 };
	enum CellFlags { NO_UNITS = 0, UNIT_PRESENT_FIXED = 3 };

	Int getType( void ) const { return m_type; }
	Int getFlags( void ) const { return m_flags; }
	ObjectID getPosUnit( void ) const { ObjectID id = m_info ? m_info->m_posUnitID : INVALID_ID; return id; }
	Bool isObstacleFence( void ) const { return m_info && (((unsigned char)(m_info->m_bfme24 >> 1)) & 1); }

	PathfindCellInfo *m_info;
	Int m_unused1;
	Int m_unused2;
	UnsignedInt m_type:3;
	UnsignedInt m_flags:3;
	UnsignedInt m_rest:26;
};

class PathfindLayer
{
public:
	PathfindCell *getCell( Int cellX, Int cellY );

private:
	unsigned char m_body[0x44];
};

class Pathfinder
{
public:
	Int clearCellForDiameter( UnsignedInt crusher, Int cellX, Int cellY, PathfindLayerEnum layer,
		Int pathDiameter, Bool stopOnFail );
	PathfindCell *getCell( PathfindLayerEnum layer, Int cellX, Int cellY );

private:
	unsigned char m_prefix[0x10];
	PathfindCell **m_map;
	IRegion2D m_extent;
	unsigned char m_mid[0x85c - 0x24];
	PathfindLayer m_layers[16];
};

inline PathfindCell *Pathfinder::getCell( PathfindLayerEnum layer, Int cellX, Int cellY )
{
	if (cellX >= m_extent.lo.x && cellX <= m_extent.hi.x &&
		cellY >= m_extent.lo.y && cellY <= m_extent.hi.y)
	{
		if (layer > LAYER_GROUND && layer <= LAYER_LAST)
		{
			PathfindCell *cell = m_layers[layer].getCell( cellX, cellY );
			if (cell)
				return cell;
		}
		return &m_map[cellX][cellY];
	}
	return 0;
}

Int Pathfinder::clearCellForDiameter( UnsignedInt crusher, Int cellX, Int cellY,
	PathfindLayerEnum layer, Int pathDiameter, Bool stopOnFail )
{
	Int radius = pathDiameter/2;
	Int numCellsAbove = radius;
	if (radius==0) numCellsAbove++;
	Int i, j;
	if (radius > 1)
	{
		for (i = cellX - radius; i < cellX + radius; i++)
		{
			Int jMax;
			Bool xMinOrMax = (i == cellX - radius) || (i == cellX + radius - 1);
			if (xMinOrMax)
			{
				jMax = cellY + radius - 1;
				j = cellY - radius + 1;
			}
			else
			{
				jMax = cellY + radius;
				j = cellY - radius;
			}
			for (; j < jMax; j++)
			{
				Object *obj;
				PathfindCell *cell = getCell(layer, i, j);
				if (!cell
					|| (cell->getFlags() == PathfindCell::UNIT_PRESENT_FIXED
						&& ((obj = TheGameLogic->findObjectByID(cell->getPosUnit())) != 0)
						&& (UnsignedInt)(signed char)obj->getCrushableLevel() > crusher))
				{
Fail:
					if (stopOnFail)
						return 0;
					return clearCellForDiameter(crusher, cellX, cellY, layer, pathDiameter - 2, false);
				}
				if (cell->getType() != PathfindCell::CELL_CLEAR)
				{
					if (cell->getType() != PathfindCell::CELL_OBSTACLE || !crusher ||
						!cell->isObstacleFence())
						goto Fail;
				}
			}
		}
	}
	else
	{
		for (i = cellX - radius; i < cellX + numCellsAbove; i++)
		{
			for (j = cellY - radius; j < cellY + numCellsAbove; j++)
			{
				PathfindCell *cell = getCell(layer, i, j);
				if (!cell)
					return 0;
				if (cell->getFlags() == PathfindCell::UNIT_PRESENT_FIXED)
				{
					Object *obj = TheGameLogic->findObjectByID(cell->getPosUnit());
					if (obj && (UnsignedInt)(signed char)obj->getCrushableLevel() > crusher)
						return 0;
				}
				if (cell->getType() != PathfindCell::CELL_CLEAR)
				{
					if (cell->getType() != PathfindCell::CELL_OBSTACLE || !crusher ||
						!cell->isObstacleFence())
						return 0;
				}
			}
		}
	}
	if (radius == 0)
		return 1;
	return 2*radius;
}
